#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int y, capacity, flow, cost;
    Edge() {}
    Edge(int y, int capacity, int flow, int cost) : y(y), capacity(capacity), flow(flow), cost(cost) {}
};

vector<Edge> edges;
const int MAX_N = 14043;
vector<int> graph[MAX_N];

long long total_cost = 0;
long long dist[MAX_N];
int parent[MAX_N], parent_edge[MAX_N], in_queue[MAX_N];

const long long INF = 1e18;
int source = MAX_N - 2;
int sink = MAX_N - 1;

int remaining(int idx) {
    return edges[idx].capacity - edges[idx].flow;
}

void augment_flow() {
    for (int i = 0; i < MAX_N; i++) {
        dist[i] = INF;
        parent[i] = -1;
        parent_edge[i] = -1;
        in_queue[i] = 0;
    }
    dist[source] = 0;
    queue<int> q;
    q.push(source);
    in_queue[source] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        in_queue[u] = 0;
        for (auto e_idx : graph[u]) {
            if (remaining(e_idx) == 0) continue;
            int y = edges[e_idx].y;
            int cst = edges[e_idx].cost;
            if (dist[y] > dist[u] + cst) {
                dist[y] = dist[u] + cst;
                parent[y] = u;
                parent_edge[y] = e_idx;
                if (!in_queue[y]) {
                    in_queue[y] = 1;
                    q.push(y);
                }
            }
        }
    }
    int current = sink;
    while (current != source) {
        edges[parent_edge[current]].flow++;
        edges[parent_edge[current] ^ 1].flow--;
        current = parent[current];
    }
    total_cost += dist[sink];
}

void add_edge(int from, int to, int cap, int cst) {
    graph[from].push_back(edges.size());
    edges.emplace_back(to, cap, 0, cst);
    graph[to].push_back(edges.size());
    edges.emplace_back(from, 0, 0, -cst);
}

int main() {
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; i++) {
        int x; cin >> x; --x;
        add_edge(source, x, 1, 0);
    }
    int tt = 101;
    for (int i = 0; i < tt; i++)
        add_edge(i * n, sink, k, i * c);
    for (int i = 0; i < m; i++) {
        int x, y; cin >> x >> y; --x; --y;
        for (int i = 0; i < tt - 1; i++) {
            for (int j = 0; j < k; j++) {
                add_edge(x + i * n, y + i * n + n, 1, d * (j * 2 + 1));
            }
        }
        for (int i = 0; i < tt - 1; i++) {
            for (int j = 0; j < k; j++) {
                add_edge(y + i * n, x + i * n + n, 1, d * (j * 2 + 1));
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < tt - 1; j++) {
            add_edge(i + j * n, i + j * n + n, k, 0);
        }
    }
    for (int i = 0; i < k; i++) {
        augment_flow();
    }
    cout << total_cost << endl;
}
